package report
import live "wind-farm-summary/internal/aggregate"
func Build(readings []int) int { return live.SumOutput(readings) }

files.internal/aggregate/sum.go:
package aggregate
func SumOutput(readings []int) int {
    result := 0
    for _, value := range readings { result += value }
    return result
}

files.internal/previous/peak.go:
package previous
func SumOutput(readings []int) int {
    result := 0
    for _, value := range readings { if value > result { result = value } }
    return result
}
